class Solution:
    def isSelfCrossing(self, distance):
        pts = [(0, 0)]
        dirs = [(0, 1), (-1, 0), (0, -1), (1, 0)]
        x = y = 0
        for i, d in enumerate(distance):
            dx, dy = dirs[i % 4]
            x += dx * d
            y += dy * d
            pts.append((x, y))

        def orient(a, b, c):
            v = (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])
            return 0 if v == 0 else (1 if v > 0 else -1)

        def onSeg(a, b, c):
            return min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= c[1] <= max(a[1], b[1])

        def inter(p1, p2, p3, p4):
            o1, o2 = orient(p1, p2, p3), orient(p1, p2, p4)
            o3, o4 = orient(p3, p4, p1), orient(p3, p4, p2)
            if o1 != o2 and o3 != o4:
                return True
            if o1 == 0 and onSeg(p1, p2, p3): return True
            if o2 == 0 and onSeg(p1, p2, p4): return True
            if o3 == 0 and onSeg(p3, p4, p1): return True
            if o4 == 0 and onSeg(p3, p4, p2): return True
            return False

        n = len(pts)
        for i in range(3, n):
            for j in range(1, i - 1):
                if inter(pts[j-1], pts[j], pts[i-1], pts[i]):
                    return True
        return False

