class Solution {
public:
    bool isSelfCrossing(vector<int>& distance) {
        vector<pair<long long,long long>> pts{{0,0}};
        int dx[4]={0,-1,0,1}, dy[4]={1,0,-1,0};
        long long x=0,y=0;
        for(int i=0;i<(int)distance.size();i++){
            x+=(long long)dx[i%4]*distance[i];
            y+=(long long)dy[i%4]*distance[i];
            pts.push_back({x,y});
        }
        auto orient=[&](auto&a,auto&b,auto&c){
            long long v=(b.first-a.first)*(c.second-a.second)-(b.second-a.second)*(c.first-a.first);
            return v==0?0:(v>0?1:-1);
        };
        auto onSeg=[&](auto&a,auto&b,auto&c){
            return min(a.first,b.first)<=c.first&&c.first<=max(a.first,b.first)
                && min(a.second,b.second)<=c.second&&c.second<=max(a.second,b.second);
        };
        auto inter=[&](auto&p1,auto&p2,auto&p3,auto&p4){
            int o1=orient(p1,p2,p3),o2=orient(p1,p2,p4),o3=orient(p3,p4,p1),o4=orient(p3,p4,p2);
            if(o1!=o2&&o3!=o4)return true;
            if(o1==0&&onSeg(p1,p2,p3))return true;
            if(o2==0&&onSeg(p1,p2,p4))return true;
            if(o3==0&&onSeg(p3,p4,p1))return true;
            if(o4==0&&onSeg(p3,p4,p2))return true;
            return false;
        };
        int n=pts.size();
        for(int i=3;i<n;i++)
            for(int j=1;j<i-1;j++)
                if(inter(pts[j-1],pts[j],pts[i-1],pts[i]))return true;
        return false;
    }
};

