class Solution {
    public boolean isSelfCrossing(int[] distance) {
        int n = distance.length;
        long[] px = new long[n + 1], py = new long[n + 1];
        int[] dx = {0, -1, 0, 1}, dy = {1, 0, -1, 0};
        for (int i = 0; i < n; i++) {
            px[i + 1] = px[i] + (long) dx[i % 4] * distance[i];
            py[i + 1] = py[i] + (long) dy[i % 4] * distance[i];
        }
        for (int i = 3; i <= n; i++)
            for (int j = 1; j < i - 1; j++)
                if (intersect(px[j-1], py[j-1], px[j], py[j], px[i-1], py[i-1], px[i], py[i])) return true;
        return false;
    }
    private boolean intersect(long ax, long ay, long bx, long by, long cx, long cy, long ex, long ey) {
        long o1 = orient(ax, ay, bx, by, cx, cy), o2 = orient(ax, ay, bx, by, ex, ey);
        long o3 = orient(cx, cy, ex, ey, ax, ay), o4 = orient(cx, cy, ex, ey, bx, by);
        if (o1 != o2 && o3 != o4) return true;
        if (o1 == 0 && onSeg(ax, ay, bx, by, cx, cy)) return true;
        if (o2 == 0 && onSeg(ax, ay, bx, by, ex, ey)) return true;
        if (o3 == 0 && onSeg(cx, cy, ex, ey, ax, ay)) return true;
        if (o4 == 0 && onSeg(cx, cy, ex, ey, bx, by)) return true;
        return false;
    }
    private long orient(long ax, long ay, long bx, long by, long cx, long cy) {
        long v = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
        return v == 0 ? 0 : (v > 0 ? 1 : -1);
    }
    private boolean onSeg(long ax, long ay, long bx, long by, long cx, long cy) {
        return Math.min(ax, bx) <= cx && cx <= Math.max(ax, bx)
            && Math.min(ay, by) <= cy && cy <= Math.max(ay, by);
    }
}

